revision "2025-02-24" {
     description "Renamed Adapter Entity to Origin Entity. Added Geo-Information";
     or-teiv-yext:label 1.1.0;
     reference "O-RAN.WG10.TE&IV-DM.0-R004-v02.00";
     }
     revision "2024-10-10" {
     description "Initial revision.";
